//! Material 3 Expressive tokens for the window: colour roles, the shape
//! scale, the type scale and state layers. The terminal keeps `NIGHT`; the
//! window's chrome (sidebar, header, composer, dialogs, panels) draws from
//! these roles only, so the whole look changes in one place.
//!
//! The colour roles are the Material 3 dark scheme (Tonal Spot, the default
//! dynamic-colour variant) generated by material-color-utilities from
//! shroom's accent `#7ec48c` as the seed. They are baked in as constants:
//! regenerate them with the same algorithm if the seed ever changes.

/// The colour roles of one Material 3 scheme, `0xRRGGBB`.
#[derive(Clone, Copy, Debug)]
pub struct Scheme {
    pub primary: u32,
    pub on_primary: u32,
    pub primary_container: u32,
    pub on_primary_container: u32,
    pub inverse_primary: u32,
    pub primary_fixed: u32,
    pub primary_fixed_dim: u32,
    pub on_primary_fixed: u32,
    pub on_primary_fixed_variant: u32,
    pub secondary: u32,
    pub on_secondary: u32,
    pub secondary_container: u32,
    pub on_secondary_container: u32,
    pub secondary_fixed: u32,
    pub secondary_fixed_dim: u32,
    pub on_secondary_fixed: u32,
    pub on_secondary_fixed_variant: u32,
    pub tertiary: u32,
    pub on_tertiary: u32,
    pub tertiary_container: u32,
    pub on_tertiary_container: u32,
    pub tertiary_fixed: u32,
    pub tertiary_fixed_dim: u32,
    pub on_tertiary_fixed: u32,
    pub on_tertiary_fixed_variant: u32,
    pub error: u32,
    pub on_error: u32,
    pub error_container: u32,
    pub on_error_container: u32,
    pub surface: u32,
    pub surface_dim: u32,
    pub surface_tint: u32,
    pub surface_variant: u32,
    pub surface_container_lowest: u32,
    pub surface_container_low: u32,
    pub surface_container: u32,
    pub surface_container_high: u32,
    pub surface_container_highest: u32,
    pub surface_bright: u32,
    pub on_surface: u32,
    pub on_surface_variant: u32,
    pub outline: u32,
    pub outline_variant: u32,
    pub inverse_surface: u32,
    pub inverse_on_surface: u32,
    pub shadow: u32,
    pub scrim: u32,
}

