/// The scheme the window paints with.
pub const M3: Scheme = DARK;

// ------------------------------------------------------------------ shapes
// The M3 Expressive corner scale, in px at zoom 1 (`ShapeTokens`).

pub mod shape {
    pub const NONE: f32 = 0.;
    pub const EXTRA_SMALL: f32 = 4.;
    pub const SMALL: f32 = 8.;
    pub const MEDIUM: f32 = 12.;
    pub const LARGE: f32 = 16.;
    pub const LARGE_INCREASED: f32 = 20.;
    pub const EXTRA_LARGE: f32 = 28.;
    pub const EXTRA_LARGE_INCREASED: f32 = 32.;
    pub const EXTRA_EXTRA_LARGE: f32 = 48.;
    /// Fully round: half the component's shorter side.
    pub const FULL: f32 = f32::INFINITY;

    /// `corner` on a component `height` px tall (FULL becomes a pill).
    pub fn radius(corner: f32, height: f32) -> f32 {
        corner.min(height / 2.)
    }
}

