// -------------------------------------------------------------------- type
// The M3 type scale (`TypeScaleTokens`), px at zoom 1. The spec's face is
// Roboto Flex; the window draws Inter (bundled as Shroom Sans, with the
// Medium weight the scale's 500 needs). gpui has no letter spacing, so the
// tracking is recorded but not applied.

pub mod font {
    use gpui::FontWeight;

    /// One type role: size, line height, weight, tracking (px).
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct Type {
        pub size: f32,
        pub line: f32,
        pub weight: FontWeight,
        pub tracking: f32,
    }

    const fn t(size: f32, line: f32, weight: f32, tracking: f32) -> Type {
        Type {
            size,
            line,
            weight: FontWeight(weight),
            tracking,
        }
    }

    pub const DISPLAY_LARGE: Type = t(57., 64., 400., -0.25);
    pub const DISPLAY_MEDIUM: Type = t(45., 52., 400., 0.);
    pub const DISPLAY_SMALL: Type = t(36., 44., 400., 0.);
    pub const HEADLINE_LARGE: Type = t(32., 40., 400., 0.);
    pub const HEADLINE_MEDIUM: Type = t(28., 36., 400., 0.);
    pub const HEADLINE_SMALL: Type = t(24., 32., 400., 0.);
    pub const TITLE_LARGE: Type = t(22., 28., 400., 0.);
    pub const TITLE_MEDIUM: Type = t(16., 24., 500., 0.15);
    pub const TITLE_SMALL: Type = t(14., 20., 500., 0.1);
    pub const BODY_LARGE: Type = t(16., 24., 400., 0.5);
    pub const BODY_MEDIUM: Type = t(14., 20., 400., 0.25);
    pub const BODY_SMALL: Type = t(12., 16., 400., 0.4);
    pub const LABEL_LARGE: Type = t(14., 20., 500., 0.1);
    pub const LABEL_MEDIUM: Type = t(12., 16., 500., 0.5);
    pub const LABEL_SMALL: Type = t(11., 16., 500., 0.5);
}

