// ------------------------------------------------------------ state layers
// A state layer is the content colour over its container at a fixed opacity.

// `StateLayerTokens`.
pub const HOVER: f32 = 0.08;
pub const FOCUS: f32 = 0.10;
pub const PRESS: f32 = 0.10;
pub const DRAG: f32 = 0.16;
/// Scrim behind a modal dialog.
pub const SCRIM: f32 = 0.32;
/// Disabled content and containers (`*DisabledOpacity` tokens).
pub const DISABLED_CONTENT: f32 = 0.38;
pub const DISABLED_CONTAINER: f32 = 0.1;

/// `content` laid over `container` at `opacity`, as one opaque colour.
pub fn layer(container: u32, content: u32, opacity: f32) -> u32 {
    shroom_ui::motion::mix(container, content, f64::from(opacity.clamp(0., 1.)))
}

#[cfg(test)]
mod tests {
    use super::*;
    use shroom_ui::contrast;

    #[test]
    fn content_roles_read_on_their_containers() {
        let s = M3;
        let pairs = [
            ("on_surface/surface", s.on_surface, s.surface),
            (
                "on_surface/container_high",
                s.on_surface,
                s.surface_container_high,
            ),
            (
                "on_surface_variant/surface",
                s.on_surface_variant,
                s.surface,
            ),
            (
                "on_surface_variant/container_highest",
                s.on_surface_variant,
                s.surface_container_highest,
            ),
            ("on_primary/primary", s.on_primary, s.primary),
            (
                "on_primary_container/primary_container",
                s.on_primary_container,
                s.primary_container,
            ),
            (
                "on_secondary_container/secondary_container",
                s.on_secondary_container,
                s.secondary_container,
            ),
            (
                "on_error_container/error_container",
                s.on_error_container,
                s.error_container,
            ),
        ];
        for (name, fg, bg) in pairs {
            let ratio = contrast(fg, bg);
            assert!(ratio >= 4.5, "{name}: {ratio:.2}:1");
        }
    }

    #[test]
    fn surfaces_climb_in_tone() {
        let s = M3;
        let luma = |c: u32| (c >> 16 & 0xff) + (c >> 8 & 0xff) + (c & 0xff);
        let ladder = [
            s.surface_container_lowest,
            s.surface,
            s.surface_container_low,
            s.surface_container,
            s.surface_container_high,
            s.surface_container_highest,
        ];
        assert!(ladder.windows(2).all(|w| luma(w[0]) < luma(w[1])));
    }

    #[test]
    fn layer_is_a_mix() {
        assert_eq!(layer(0x000000, 0xffffff, 0.), 0x000000);
        assert_eq!(layer(0x000000, 0xffffff, 1.), 0xffffff);
    }
}
